"""Minimal YAML renderer — standard library only."""

from plugins import PluginError, Renderer, register


def _yaml_value(value) -> str:
    """Serialize a single scalar value to YAML."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    if isinstance(value, str):
        # Quote if the string could be misinterpreted or is empty
        if value == "" or value in ("true", "false", "null", "yes", "no",
                                     "on", "off", "True", "False", "Null",
                                     "Yes", "No", "On", "Off",
                                     "~", "y", "Y", "n", "N"):
            return "'" + value.replace("'", "''") + "'"
        # Quote if it starts/ends with whitespace or contains special chars
        if (value[0] in (' ', '\t') or value[-1] in (' ', '\t')
                or any(c in value for c in (':', '{', '}', '[', ']',
                                            ',', '&', '*', '#', '?', '|',
                                            '-', '<', '>', '=', '!', '%',
                                            '@', '`'))):
            return "'" + value.replace("'", "''") + "'"
        return value
    return str(value)


def _yaml_dump(rows: list[dict]) -> str:
    """Dump a list of flat dicts into a YAML string."""
    if not rows:
        return ""
    keys = list(rows[0].keys())
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for k in keys:
            lines.append(f"  {k}: {_yaml_value(row[k])}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _yaml_dump(rows)

